// ------------------------------------------------------------------
// Protobuf message layouts (in-memory, per module)
// ------------------------------------------------------------------
// type: protobuf wire type (see proto_type_name), label: 1=optional 2=required 3=repeated,
// has_bit: index in the has-bits word (-1 = none), offset/has_bits_offset in bytes (-1 = n/a).
struct ProtoField {
    const char* name;
    int32_t offset;      // -1 when the field has no static offset
    int number;
    int32_t has_bit;     // -1 when none
    uint32_t type;
    uint32_t label;
};

struct ProtoMessage {
    const char* name;
    int32_t size;
    int32_t has_bits_offset;  // -1 when none
    const ProtoField* fields;
    int field_count;
};

struct ProtoModule {
    const char* module_name;
    const ProtoMessage* messages;
    int message_count;
};

